class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int countValidSequences(int n, int k) {
    int size = n + k + 5;
    long[] fact = new long[size], inv = new long[size];
    fact[0] = 1;
    for (int i = 1; i < size; i++) fact[i] = fact[i - 1] * i % MOD;
    inv[size - 1] = pow(fact[size - 1], MOD - 2);
    for (int i = size - 1; i > 0; i--) inv[i - 1] = inv[i] * i % MOD;
    long total = comb(fact, inv, n - 1, k - 1);
    long allOdd = 0;
    if ((n - k) % 2 == 0) allOdd = comb(fact, inv, (n - k) / 2 + k - 1, k - 1);
    return (int) (((total - allOdd) % MOD + MOD) % MOD);
  }

  private static long comb(long[] fact, long[] inv, int a, int b) {
    if (b < 0 || b > a) return 0;
    return fact[a] * inv[b] % MOD * inv[a - b] % MOD;
  }
}
